'use strict';
const $=s=>document.querySelector(s),app=$('#app'),E=Engine;
let lang=localStorage.getItem('m04-language')||'pt',screen=1,mode='local',players=[],revealIndex=0,showRole=false,tab='instrument',review=false,event=false,room=null,session=null,poller=null,lastVersion=-1,connection=true;
let state=E.initial(),draftNames=['','','',''],pendingInvite=null;
const t=(pt,en)=>lang==='en'?en:pt;
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=['Azul / Estrela','Amarelo / Sol','Verde / Folha','Vermelho / Raio'];
const symbols=['✦','+','◇','/'];const colors=['#6d9afa','#f9d362','#72c692','#ea655f'];
function characterName(i){return [t('Azul · Estrela','Blue · Star'),t('Amarelo · Sol','Yellow · Sun'),t('Verde · Folha','Green · Leaf'),t('Vermelho · Raio','Red · Bolt')][i]}
function job(i){return [t('Comandante','Commander'),t('Engenharia','Engineering'),t('Ciência','Science'),t('Operações','Operations')][i]}
function duty(i){return [t('Conduza o debate e confirme a hipótese, os componentes e o lançamento.','Lead the discussion and confirm the hypothesis, components and launch.'),t('Confira massa, energia e orçamento. Explique os limites dos componentes.','Check mass, power and budget. Explain component limitations.'),t('Escolha evidências que testem a hipótese e avalie a utilidade dos sensores.','Choose evidence to test the hypothesis and assess sensor usefulness.'),t('Confira órbita, lançador, transmissão e frequência de observação.','Check orbit, launcher, transmission and observation frequency.')][i]}
function missions(){return [{name:t('O ÚLTIMO SINAL','THE LAST SIGNAL'),brief:t('Recife, 2049. Temperaturas urbanas elevadas e resfriamento oceânico contradizem uma pequena oscilação solar. Investiguem a origem do sinal.','Recife, 2049. Urban warming and ocean cooling contradict a small solar fluctuation. Investigate the signal’s origin.'),goal:t('Comparar evidências solares, atmosféricas e térmicas.','Compare solar, atmospheric and thermal evidence.'),challenge:t('Um único sensor deixa hipóteses sem teste. A anomalia é ficção científica.','A single sensor leaves hypotheses untested. The anomaly is science fiction.'),hyp:[t('Variação solar','Solar variation'),t('Composição atmosférica','Atmospheric composition'),t('Aquecimento da superfície','Surface warming')]},{name:t('LINHA D’ÁGUA','FLOODLINE'),brief:t('Chuvas e maré alta ameaçam Recife. Nuvens cobrem 85% da área. A cidade precisa de mapas frequentes das áreas inundadas.','Rain and high tides threaten Recife. Clouds cover 85% of the area. The city needs frequent flood extent maps.'),goal:t('Mapear águas superficiais durante tempestades.','Map surface water during storms.'),challenge:t('Nuvens bloqueiam a câmera óptica. Radar exige mais energia e transmissão.','Clouds block optical cameras. Radar requires more power and transmission.'),hyp:[t('Chuva e rios','Rain and rivers'),t('Marés e costa','Tides and coast'),t('Combinação dos fatores','Combined factors')]},{name:t('LINHA DE CALOR','HEATLINE'),brief:t('Bairros impermeabilizados aquecem mais que áreas vegetadas. A equipe deve investigar as ilhas de calor de Recife.','Paved neighborhoods warm more than vegetated areas. Investigate Recife’s urban heat islands.'),goal:t('Mapear a temperatura da superfície e comparar o uso do solo.','Map surface temperature and compare land use.'),challenge:t('Temperatura da superfície não é temperatura do ar. Uma imagem não prova causalidade.','Surface temperature is not air temperature. One image does not prove causality.'),hyp:[t('Variação solar','Solar variation'),t('Urbanização e vegetação','Urbanization and vegetation'),t('Tendência global isolada','Global trend alone')]}]}
const English={cruise:['Interplanetary transfer','Heliocentric transfer in the inner Solar System; requires a medium launcher.'],optical:['Multispectral camera','Maps vegetation, urban land and water. Clouds block observations.'],radar:['Synthetic aperture radar','Maps water at night and through clouds. High power and data demand.'],thermal:['Thermal infrared sensor','Measures surface temperature, not air temperature.'],solar:['Solar radiometer','Tests changes in incoming solar energy.'],atmos:['Atmospheric spectrometer','Investigates atmospheric signatures and anomaly patterns.'],basic:['Compact panels','65 W available. Lightweight power for smaller payloads.'],large:['Expanded panels','145 W available. Supports demanding instruments.'],low:['S band','5 GB/day. Low cost, limited bandwidth.'],high:['X band','18 GB/day. Supports larger payloads.'],leo:['LEO · 550 km','Inclined low orbit. Regional revisit every 3 cycles.'],sun:['Sun-synchronous · 700 km','Comparable illumination. Revisit every 2 cycles. Requires a medium launcher.'],light:['Light launcher','Up to 360 kg. Compatible with inclined LEO only.'],medium:['Medium launcher','Up to 620 kg. Compatible with both orbits.']};
function itemName(id){const x=Object.values(E.catalog).flat().find(x=>x.id===id);return lang==='en'?English[id][0]:x.name}
function itemDesc(o){return lang==='en'?English[o.id][1]:o.desc}
function group(g){return {instrument:t('Instrumentos','Instruments'),energy:t('Energia','Power'),comms:t('Comunicação','Communications'),orbit:t('Órbita','Orbit'),launcher:t('Lançador','Launcher')}[g]}
const CHARACTER_ASSETS=["data:image/svg+xml;base64,","data:image/svg+xml;base64,","data:image/svg+xml;base64,","data:image/svg+xml;base64,"];
function astronaut(i,large=false){return '<span class="astronaut '+(large?'crew-large':'')+'" role="img" aria-label="'+characterName(i)+'"><img src="'+CHARACTER_ASSETS[i]+'" alt="" draggable="false" width="110" height="181"></span>'}
function scene(){return `<div class="scene"><div class="scene-caption">${t('MARCO ZERO · CENTRO DE COMANDO','MARCO ZERO · MISSION CONTROL')}</div><svg viewBox="0 0 160 104" shape-rendering="crispEdges" aria-hidden="true"><path fill="#152d61" d="M0 0h160v104H0z"/><path fill="#f6f2df" d="M16 18h1v1h-1zM38 9h1v1h-1zM67 24h1v1h-1zM134 12h1v1h-1zM147 40h1v1h-1zM29 37h1v1h-1z"/><path fill="#3454ad" d="M84 18h29v3h9v5h6v8h3v22h-3v8h-6v5h-9v3H84v-3h-9v-5h-6v-8h-3V34h3v-8h6v-5h9z"/><path fill="#72c692" d="M80 25h16v5h8v8h-7v10h-8v13h-6V49h-6V38h-6v-7h9zM114 48h11v9h-5v7h-9v-8h-5v-5h8z"/><path fill="#f6f2df" d="M87 20h20v2H87zM70 35h5v3h-5zM107 32h17v2h-17z"/><path fill="#10234b" d="M0 69h160v35H0z"/><path fill="#607fba" d="M0 77h160v3H0z"/><path fill="#294a87" d="M0 90h160v14H0z"/><path fill="#f6f2df" d="M9 52h13v25H9zM7 50h17v4H7zM29 61h19v16H29zM34 54h9v8h-9zM138 57h12v20h-12z"/><path fill="#ea655f" d="M11 57h3v4h-3zM17 57h3v4h-3zM11 65h3v4h-3zM17 65h3v4h-3z"/><path fill="#f9d362" d="M26 73h26v2H26zM137 63h14v2h-14zM96 79h2v10h-2z"/></svg><div class="scene-crew">${[0,1,2,3].map(i=>astronaut(i)).join('')}</div></div>`}
function header(){document.documentElement.lang=lang==='en'?'en':'pt-BR';$('#language').value=lang;$('#foot').textContent=t('RECIFE, PE · FICÇÃO E CIÊNCIA · 4 JOGADORES','RECIFE, BRAZIL · FICTION & SCIENCE · 4 PLAYERS');$('#sources').textContent=t('Fontes e ciência ↗','Sources & science ↗')}
function nav(){return `<nav class="steps" aria-label="${t('Etapas','Steps')}">${[t('Início','Home'),t('Jogadores','Players'),t('Missão','Mission'),t('Montagem','Assembly'),t('Resultado','Result')].map((x,i)=>`<span class="${screen===i+1?'active':''}" ${screen===i+1?'aria-current="step"':''}><b class="stepno">0${i+1}</b>${x}</span>`).join('')}</nav>`}
function showModal(html){$('#modalBody').innerHTML=html;$('#modal').showModal()}
$('.close').onclick=()=>$('#modal').close();
$('#language').onchange=()=>{lang=$('#language').value;localStorage.setItem('m04-language',lang);render()};
$('#home').onclick=e=>{e.preventDefault();if(room){showModal(`<h2>${t('Partida online ativa','Online game active')}</h2><p>${t('Sair desta tela não encerra a sala. Você pode voltar pelo mesmo link neste navegador.','Leaving this screen does not close the room. You can return using the same link in this browser.')}</p><button id="leave">${t('Voltar ao início','Return home')}</button>`);$('#leave').onclick=()=>{$('#modal').close();exitRoom();screen=1;render()}}else{screen=1;showRole=false;render()}};
$('#sources').onclick=()=>showModal(`<h2>${t('Ficção com ciência','Fiction with science')}</h2><p>${t('Os acontecimentos de 2049 e todos os números da simulação são fictícios e simplificados. Não há dados em tempo real. O satélite observa a Terra; ele não impede desastres. Temperatura da superfície não equivale à do ar.','The events in 2049 and all simulation values are fictional and simplified. No live data is used. The satellite observes Earth; it does not prevent disasters. Surface temperature differs from air temperature.')}</p><ul><li><a href="https://www.jpl.nasa.gov/go/opera/" target="_blank" rel="noopener">NASA OPERA</a></li><li><a href="https://ecostress.jpl.nasa.gov/" target="_blank" rel="noopener">NASA ECOSTRESS</a></li><li><a href="https://gpm.nasa.gov/" target="_blank" rel="noopener">NASA GPM</a></li><li><a href="https://airs.jpl.nasa.gov/" target="_blank" rel="noopener">NASA AIRS</a></li><li><a href="https://data.giss.nasa.gov/gistemp/" target="_blank" rel="noopener">NASA GISTEMP</a></li></ul><p>${t('Pontuação preservada: 70% ciência, 20% viabilidade técnica e 10% eficiência. O resultado usa o retorno científico: ≥65 sucesso; ≥35 parcial; abaixo de 35, insucesso. Encontrar o impostor não substitui o objetivo científico.','Preserved scoring: 70% science, 20% technical feasibility, 10% efficiency. Outcome uses scientific return: ≥65 success; ≥35 partial; below 35 failure. Finding the impostor does not replace the scientific objective.')}</p>`);
function save(){if(mode==='local'&&players.length===4){try{sessionStorage.setItem('m04-local-v2',JSON.stringify({screen,state,players,revealIndex,tab,review,event}))}catch{}}}
function render(){if(pendingInvite&&!room){incoming(pendingInvite);return}const focused=document.activeElement?.id,message=$('#chatText')?.value,openCouncil=$('.review details')?.open||$('#suspect')?.closest('details')?.open;header();app.innerHTML=nav()+'<section id="view" class="shake"></section>';if(screen===1)home();if(screen===2)lobby();if(screen===3)brief();if(screen===4)build();if(screen===5)results();if(message&&$('#chatText'))$('#chatText').value=message;if(openCouncil&&$('#suspect'))$('#suspect').closest('details').open=true;if(focused==='chatText')$('#chatText')?.focus();save()}
const view=html=>$('#view').innerHTML=html;
function home(){view(`<div class="hero"><div><div class="rainbow"><span></span><span></span><span></span><span></span></div><div class="eyebrow">${t('Uma missão feita por quatro pessoas','A mission built by four people')}</div><h1>MARCO 04<br>SPACE<span style="color:var(--yellow)">.</span></h1><p>${t('Construam um satélite para investigar o clima de Recife. Escolham os componentes, equilibrem recursos e descubram em quem confiar.','Build a satellite to investigate Recife’s climate. Choose components, balance resources and decide whom to trust.')}</p><button class="primary" id="start">${t('Começar →','Start →')}</button></div>${scene()}</div><h2>${t('Como jogar','How to play')}</h2><div class="grid"><div class="card"><span class="pixel-icon">01 / ✦</span><h3>${t('Reúnam a tripulação','Gather the crew')}</h3><p>${t('Quatro participantes recebem funções automaticamente. Um dos assessores é o impostor. Revelem os papéis em segredo.','Four participants receive roles automatically. One advisor is the impostor. Reveal roles privately.')}</p></div><div class="card"><span class="pixel-icon">02 / ▦</span><h3>${t('Construam com propósito','Build with purpose')}</h3><p>${t('Leiam a missão, testem uma hipótese e montem um satélite dentro dos limites de massa, energia e orçamento.','Read the mission, test a hypothesis and assemble a satellite within mass, power and budget limits.')}</p></div><div class="card"><span class="pixel-icon">03 / ◇</span><h3>${t('Lancem e aprendam','Launch and learn')}</h3><p>${t('Conversem, revisem a nave e enfrentem um evento. O relatório explica o que funcionou e o que melhorar.','Discuss, review the spacecraft and face an event. The report explains what worked and what to improve.')}</p></div></div><p class="hint">${t('Sem jogadores automáticos. Os quatro participantes são pessoas.','No automated players. All four participants are human.')}</p><div id="resumeSlot"></div>`);$('#start').onclick=()=>{screen=2;players=[];revealIndex=0;showRole=false;state=E.initial();review=false;event=false;render()};try{const v=JSON.parse(sessionStorage.getItem('m04-local-v2'));if(v?.players?.length===4&&v.screen>1){$('#resumeSlot').innerHTML=`<button id="resume">${t('Continuar partida presencial','Resume local game')}</button>`;$('#resume').onclick=()=>{({screen,state,players,revealIndex,tab,review,event}=v);mode='local';showRole=false;render()}}}catch{}}
function localForm(){return `<div class="grid four">${[0,1,2,3].map(i=>`<label class="player">${astronaut(i)}<div class="small">${characterName(i)}</div><span class="sr-only">${t('Nome do jogador','Player name')} ${i+1}</span><input id="name${i}" data-name="${i}" maxlength="24" value="${escapeHTML(draftNames[i])}" placeholder="${t('Nome','Name')} ${i+1}" autocomplete="off"></label>`).join('')}</div><div class="notice">${t('O jogo sorteia as quatro funções. Um dos três assessores recebe também a identidade de impostor; o comandante é sempre da equipe.','The game randomly assigns all four roles. One of the three advisors also receives the impostor identity; the commander is always loyal.')}</div><div id="formError" role="alert"></div><button class="primary" id="assign">${t('Sortear funções →','Assign roles →')}</button>`}
function lobby(){if(room){onlineLobby();return}if(players.length===4){roleScreen();return}view(`<div class="eyebrow">${t('02 / Formar equipe','02 / Build the team')}</div><h2>${t('Quatro cores. Uma tripulação.','Four colors. One crew.')}</h2><p>${t('Escolham como participar e cadastrem os nomes antes de revelar as funções.','Choose how to play and enter names before revealing roles.')}</p><div class="two"><button id="localMode" class="card ${mode==='local'?'selected':''}"><h3>${t('Presencial','In person')}</h3><span class="small">${t('Quatro pessoas no mesmo dispositivo.','Four people on the same device.')}</span></button><button id="onlineMode" class="card ${mode==='online'?'selected':''}"><h3>${t('Online por link','Online via link')}</h3><span class="small">${t('Uma pessoa por dispositivo, na mesma sala.','One person per device in the same room.')}</span></button></div><div style="margin-top:25px">${mode==='local'?localForm():`<div class="panel"><label>${t('Seu nome','Your name')}<input id="onlineName" maxlength="24" autocomplete="off" value="${escapeHTML(draftNames[0])}"></label><p>${t('Crie uma sala e compartilhe o link. A conexão só funciona quando o jogo é servido pelo servidor incluído.','Create a room and share the link. Connections work only when the game is served by the included server.')}</p><div id="serverStatus" class="notice">${t('Verificando servidor…','Checking server…')}</div><button class="primary" id="create" disabled>${t('Criar sala','Create room')}</button></div>`}</div>`);$('#localMode').onclick=()=>{mode='local';render()};$('#onlineMode').onclick=()=>{mode='online';render()};if(mode==='local'){document.querySelectorAll('[data-name]').forEach(n=>n.oninput=()=>draftNames[+n.dataset.name]=n.value);$('#assign').onclick=()=>{const ns=draftNames.map(x=>x.trim());if(ns.some(x=>!x)||new Set(ns.map(x=>x.toLowerCase())).size!==4){$('#formError').innerHTML=`<p class="notice error">${t('Preencha quatro nomes diferentes.','Enter four different names.')}</p>`;return}players=E.crew(ns);revealIndex=0;render()}}else{checkServer();$('#onlineName').oninput=e=>draftNames[0]=e.target.value;$('#create').onclick=()=>createRoom()}}
function roleScreen(){if(revealIndex>=4){screen=3;render();return}const p=players[revealIndex];view(`<div class="role panel"><div class="eyebrow">${t('Revelação secreta','Secret reveal')} ${revealIndex+1}/4</div>${astronaut(p.color)}<h2>${escapeHTML(p.name)}</h2><div id="roleSecret">${showRole?roleHTML(p):`<p>${t('Passe o dispositivo para esta pessoa. Os outros devem desviar o olhar.','Pass the device to this person. Everyone else must look away.')}</p>`}</div><button class="primary" id="reveal">${showRole?t(revealIndex===3?'Ocultar e ir para a missão':'Ocultar e passar →',revealIndex===3?'Hide and open briefing':'Hide and pass →'):t('Revelar minha função','Reveal my role')}</button></div>`);$('#reveal').onclick=()=>{if(showRole){showRole=false;revealIndex++;render()}else{showRole=true;render()}}}
function roleHTML(p){return `<div class="role-secret"><div class="role-badge">${job(p.job)}</div><h2 style="color:${p.impostor?'var(--red)':'var(--green)'}">${p.impostor?t('IMPOSTOR','IMPOSTOR'):t('TRIPULAÇÃO','CREW')}</h2><p>${duty(p.job)}</p><div class="notice ${p.impostor?'error':'success'}">${p.impostor?t('Objetivo secreto: use argumentos plausíveis para comprometer o retorno científico. Não revele sua identidade.','Secret objective: use plausible arguments to undermine scientific return. Keep your identity hidden.'):t('Objetivo: ajudar a missão a produzir evidências úteis. Questione conselhos e respeite os limites.','Objective: help the mission produce useful evidence. Question advice and respect the limits.')}</div></div>`}
function canControl(){return !room||session?.host}
function responsibilities(){return players.map(p=>`<div class="responsibility"><b>${escapeHTML(p.name)} · ${job(p.job)}</b>${duty(p.job)}</div>`).join('')}
function disabled(){return canControl()?'':'disabled'}
function brief(){const m=missions()[state.mission];view(`<div class="eyebrow">03 / ${t('Briefing da missão','Mission briefing')}</div><h2>${m.name}</h2><p class="subtitle">${m.brief}</p><div class="tabs">${missions().map((x,i)=>`<button data-mission="${i}" class="${i===state.mission?'active':''}" ${disabled()}>${x.name}</button>`).join('')}</div><div class="split"><div><div class="panel"><h3>${t('Objetivo do satélite','Satellite objective')}</h3><p>${m.goal}</p><h3>${t('Desafio','Challenge')}</h3><p>${m.challenge}</p><h3>${t('Hipótese inicial','Initial hypothesis')}</h3><div class="tabs">${m.hyp.map((x,i)=>`<button data-hyp="${i}" class="${state.hyp===i?'active':''}" ${disabled()}>${x}</button>`).join('')}</div></div><div class="notice">${t('Limites: 160 créditos. A massa deve caber no lançador, e a energia deve sustentar os sensores. Transmissão insuficiente reduz os dados úteis.','Limits: 160 credits. Mass must fit the launcher, and power must support the sensors. Insufficient transmission reduces useful data.')}</div><div class="panel"><h3>${t('Critérios de sucesso','Success criteria')}</h3><p class="small">${t('Retorno científico ≥65%: sucesso. De 35% a 64%: parcial. Abaixo de 35%: insucesso. Sensores, dados transmitidos e revisita definem esse retorno.','Scientific return ≥65%: success. From 35% to 64%: partial. Below 35%: failure. Sensors, delivered data and revisit frequency determine this return.')}</p><p class="small">${t('Pontuação geral: 70% ciência + 20% viabilidade + 10% eficiência.','Overall score: 70% science + 20% feasibility + 10% efficiency.')}</p></div><div class="actions"><button class="primary" id="toBuild" ${disabled()}>${t('Escolher componentes →','Choose components →')}</button></div>${controlNote()}</div><aside class="panel"><h3>${t('Responsabilidades','Responsibilities')}</h3>${responsibilities()}${onlineChat()}</aside></div>`);document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>change('mission',+b.dataset.mission));document.querySelectorAll('[data-hyp]').forEach(b=>b.onclick=()=>change('hyp',+b.dataset.hyp));$('#toBuild').onclick=()=>advance(4);bindChat()}
function controlNote(){return room?`<div id="connection" class="status">${connection?t('● Conectado','● Connected'):err('NETWORK')}</div><p class="hint">${t('O anfitrião opera os botões; a equipe acompanha as mudanças e debate no chat.','The host operates controls; the crew follows changes and discusses in chat.')}</p>`:''}
function validation(){const x=E.totals(state),a=[];if(!state.instruments.length)a.push(t('Selecione pelo menos um instrumento.','Select at least one instrument.'));if(x.cost>160)a.push(t('Orçamento excedido.','Budget exceeded.'));if(x.mass>x.load)a.push(t('A massa excede a capacidade do lançador.','Mass exceeds launcher capacity.'));if(x.power>x.supply)a.push(t('Energia insuficiente para operar os instrumentos.','Not enough power to operate instruments.'));if(state.orbit==='sun'&&state.launcher==='light')a.push(t('A órbita heliossíncrona exige o lançador médio.','Sun-synchronous orbit requires the medium launcher.'));return a}
function meter(name,v,max,unit){return `<div class="meter ${v>max?'over':''}"><label><span>${name}</span><span>${v}/${max} ${unit}</span></label><div class="track"><div class="fill" style="width:${Math.min(100,v/max*100)}%"></div></div></div>`}
function resources(){const x=E.totals(state);return `<aside class="panel"><h3>${t('Seu satélite','Your satellite')}</h3><div class="satellite"><span class="solarwing"></span><span class="satbus">M04</span><span class="solarwing"></span></div>${meter(t('Orçamento','Budget'),x.cost,160,t('CR','CR'))}${meter(t('Massa','Mass'),x.mass,x.load,'kg')}${meter(t('Consumo','Power use'),x.power,x.supply,'W')}${meter(t('Dados/ciclo','Data/cycle'),x.data,x.capacity,('GB/'+t('dia','day')))}<h3>${t('Já escolhido','Selected')}</h3>${selectedList()}<p class="hint">${t('Inclui plataforma-base: 100 kg, 15 W e 12 créditos. Todos os valores são simplificados.','Includes base platform: 100 kg, 15 W and 12 credits. All values are simplified.')}</p>${onlineChat()}</aside>`}
function selectedList(){return `<ul class="selected-list">${state.instruments.map(id=>`<li>${itemName(id)}<span>${group('instrument')}</span></li>`).join('')}${['energy','comms','orbit','launcher'].map(g=>`<li>${itemName(state[g])}<span>${group(g)}</span></li>`).join('')}</ul>`}
const icons={optical:'▣',radar:'⌁',thermal:'♨',solar:'☼',atmos:'≋',basic:'▥',large:'▦',low:'⌁',high:'⌁',leo:'◯',sun:'☼',light:'↑',medium:'⇈'};
function build(){if(event){eventScreen();return}const errors=validation();view(`<div class="eyebrow">04 / ${t('Oficina orbital','Orbital workshop')}</div><h2>${review?t('Revisão antes do lançamento','Pre-launch review'):t('Cada peça tem um propósito.','Every part has a purpose.')}</h2><p>${review?t('Reúnam a equipe. Confiram os componentes e os limites antes de confirmar.','Gather the crew. Check components and constraints before confirming.'):t('Escolham sensores, geração de energia, comunicação, órbita e lançador.','Choose sensors, power generation, communications, orbit and launcher.')}</p><div class="split"><section>${review?`<div class="panel"><h3>${t('Configuração final','Final configuration')}</h3>${selectedList()}<h3>${t('Hipótese','Hypothesis')}</h3><p>${missions()[state.mission].hyp[state.hyp]}</p></div>`:`<div class="tabs">${Object.keys(E.catalog).map(g=>`<button data-tab="${g}" class="${tab===g?'active':''}">${group(g)}</button>`).join('')}</div><div class="components">${E.catalog[tab].map(o=>{const active=tab==='instrument'?state.instruments.includes(o.id):state[tab]===o.id;return `<button class="component ${active?'selected':''}" data-item="${o.id}" aria-pressed="${active}" ${disabled()}><span class="symbol" aria-hidden="true">${icons[o.id]}</span><strong>${active?'✓ ':''}${itemName(o.id)}</strong><span class="desc">${itemDesc(o)}</span><span class="stats">${o.cost} CR${o.mass?' · '+o.mass+' kg':''}${o.power?' · '+o.power+' W · '+o.data+' '+('GB/'+t('dia','day')):''}</span></button>`}).join('')}</div>`}<div class="notice ${errors.length?'error':'success'}" role="status">${errors.length?errors.join('<br>'):t('✓ Configuração tecnicamente viável. Confiram também o objetivo científico.','✓ Technically feasible configuration. Check the scientific objective too.')}</div>${E.totals(state).data>E.totals(state).capacity?`<p class="notice error">${t('A transmissão será um gargalo: parte dos dados será perdida. O lançamento continua permitido.','Transmission will be a bottleneck: some data will be lost. Launch is still allowed.')}</p>`:''}${council()}<div class="actions"><button id="backBuild" ${disabled()}>${review?t('← Editar componentes','← Edit components'):t('← Briefing','← Briefing')}</button><button class="primary" id="confirmBuild" ${errors.length||!canControl()?'disabled':''}>${review?t('Confirmar montagem e lançar ↑','Confirm assembly and launch ↑'):t('Revisar montagem →','Review assembly →')}</button></div>${controlNote()}</section>${resources()}</div>`);document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>change(tab,b.dataset.item));$('#backBuild').onclick=()=>{if(review){review=false;render()}else advance(3)};$('#confirmBuild').onclick=()=>{if(review){if(room)act('launch');else{event=true;render()}}else{review=true;render()}};bindChat();const suspect=$('#suspect');if(suspect)suspect.onchange=()=>change('accused',Number(suspect.value))}
function council(){return `<details class="review panel"><summary>${t('Conselho da equipe e suspeita','Crew council and suspicion')}</summary><p class="small">${t('Discutam antes de lançar. Estas notas são orientações técnicas; os jogadores apresentam seus próprios argumentos.','Discuss before launching. These notes are technical guidance; players present their own arguments.')}</p>${[t('Confiram a energia necessária para operar todos os sensores.','Check the power needed to operate all sensors.'),t('O instrumento precisa observar a variável que a hipótese exige.','The instrument must observe the variable your hypothesis requires.'),t('Órbita e transmissão afetam a frequência e os dados entregues.','Orbit and transmission affect frequency and delivered data.')].map((s,i)=>`<div class="advice"><b>${job(i+1)}</b>${s}</div>`).join('')}<label class="small">${t('Suspeito do comandante (opcional)','Commander’s suspect (optional)')}<select id="suspect" ${disabled()}><option value="-1">${t('Nenhum','None')}</option>${players.filter(p=>p.job!==0).map(p=>`<option value="${p.id}" ${Number(state.accused)===Number(p.id)?'selected':''}>${escapeHTML(p.name)} · ${job(p.job)}</option>`).join('')}</select></label></details>`}
function eventScreen(){view(`<div class="role panel"><div class="eyebrow">04 / ${t('Lançamento confirmado','Launch confirmed')}</div><div class="symbol" style="font-size:65px">↑</div><h2>${t('Satélite em órbita!','Satellite in orbit!')}</h2><p>${t('Comando em Recife. Lançamento fictício contratado em Alcântara, Maranhão.','Mission control in Recife. Fictional launch contracted from Alcântara, Maranhão.')}</p><div class="notice">${state.mission===1?t('Uma tempestade aumentou em 25% o fluxo de observações. A janela de contato ficou menor.','A storm increased observation data flow by 25%. The contact window is shorter.'):t('Interferência na estação: observar agora descarta 25% adicionais dos dados; esperar reduz a frequência de observação.','Ground station interference: observing now discards an extra 25% of data; waiting reduces observation frequency.')}</div><button id="now" class="primary" ${disabled()}>${t('Observar agora','Observe now')}</button><p class="small">${t('Resposta rápida; aceite perda de dados.','Rapid response; accept data loss.')}</p><button id="wait" ${disabled()}>${t('Aguardar contato estável','Wait for a stable contact')}</button><p class="small">${t('Preserve os dados; aceite menor frequência.','Preserve data; accept lower frequency.')}</p>${controlNote()}${onlineChat()}</div>`);$('#now').onclick=()=>finish('now');$('#wait').onclick=()=>finish('wait');bindChat()}
function finish(choice){if(room)act('finish',{choice});else{state.eventChoice=choice;screen=5;render()}}
function results(){const r=E.evaluate(state),x=E.totals(state),has=id=>state.instruments.includes(id),good=[],bad=[],improve=[];
if(r.technical===100)good.push(t('Massa, energia, orçamento e lançador compatíveis.','Mass, power, budget and launcher are compatible.'));
const relevant=state.mission===0?'atmos':state.mission===1?'radar':'thermal';
if(has(relevant))good.push(t('O instrumento principal foi escolhido: ','The primary instrument was selected: ')+itemName(relevant)+'.');else{bad.push(t('Faltou o instrumento principal: ','The primary instrument was missing: ')+itemName(relevant)+'.');improve.push(t('Incluam ','Include ')+itemName(relevant)+t(' para observar a variável da missão.',' to observe the mission variable.'))}
if(state.mission===1&&!has('radar'))bad.push(t('Nuvens bloquearam boa parte das imagens ópticas.','Clouds blocked much of the optical imagery.'));
if(state.mission!==1&&has('optical'))good.push(t('A câmera forneceu contexto de vegetação e ocupação urbana.','The camera provided vegetation and urban land-use context.'));
if(x.data>x.capacity){bad.push(t('A antena não transmitiu todo o fluxo dos instrumentos.','The antenna could not transmit the full instrument data flow.'));improve.push(t('Escolham banda X ou reduzam a quantidade de sensores.','Choose X band or reduce the number of sensors.'))}else good.push(t('A transmissão nominal comportava o fluxo de dados.','Nominal transmission supported the data flow.'));
if(state.eventChoice==='now'){bad.push(t('A resposta imediata ficou sujeita a perda de dados durante o evento.','Immediate response was exposed to data loss during the event.'));improve.push(t('Comparem urgência e qualidade antes de escolher a janela de contato.','Compare urgency and quality before choosing a contact window.'))}else{bad.push(t('Esperar o contato estável reduziu a frequência de observação em 20%.','Waiting for stable contact reduced observation frequency by 20%.'));improve.push(t('Uma órbita com melhor revisita ajuda a reduzir lacunas de observação.','An orbit with better revisit helps reduce observation gaps.'))}
if(state.mission===0&&state.instruments.length<3)improve.push(t('Comparem instrumentos atmosféricos, solares e térmicos para distinguir hipóteses.','Compare atmospheric, solar and thermal instruments to distinguish hypotheses.'));
if(state.mission===2&&!has('optical'))improve.push(t('Adicionem a câmera multiespectral para relacionar calor e vegetação.','Add a multispectral camera to relate heat and vegetation.'));
if(!improve.length)improve.push(t('Comparem outras configurações e seus custos.','Compare other configurations and their costs.'));
const mole=players.find(p=>p.impostor),status=r.science>=65?t('MISSÃO BEM-SUCEDIDA','MISSION SUCCESS'):r.science>=35?t('SUCESSO PARCIAL','PARTIAL SUCCESS'):t('MISSÃO SEM SUCESSO','MISSION UNSUCCESSFUL');
view(`<div class="eyebrow">05 / ${t('Resultado final','Final result')}</div><h2>${status}</h2><div class="two"><div class="panel"><div class="score">${r.score}<small style="font-size:20px">/100</small></div><p>${t('Pontuação geral','Overall score')}</p>${meter(t('Ciência','Science'),r.science,100,'%')}${meter(t('Viabilidade','Feasibility'),r.technical,100,'%')}${meter(t('Eficiência','Efficiency'),r.efficiency,100,'%')}</div><div class="panel"><h3>${missions()[state.mission].name}</h3><p>${t('Dados entregues','Delivered data')}: <strong>${r.delivered}%</strong></p><p>${t('Hipótese inicial','Initial hypothesis')}: <strong>${missions()[state.mission].hyp[state.hyp]}</strong></p><p class="small">${state.mission===1?t('O mapa de água precisa ser combinado com medições locais de chuva, rios e marés para investigar a causa.','The water map must be combined with local rain, river and tide measurements to investigate the cause.'):r.science<35?t('Evidências insuficientes para uma conclusão.','Insufficient evidence for a conclusion.'):state.hyp===1?t('As observações sintéticas são compatíveis com a hipótese, mas não provam causalidade sozinhas.','The synthetic observations are consistent with the hypothesis but do not prove causality alone.'):t('Os dados favorecem uma explicação alternativa. Rever a hipótese faz parte da ciência.','The data favor an alternative explanation. Revising hypotheses is part of science.')}</p><div class="notice">${t('O impostor era','The impostor was')}: <strong>${escapeHTML(mole?.name||'—')}</strong><br>${Number(state.accused)===Number(mole?.id)?t('O comandante identificou o suspeito correto.','The commander identified the correct suspect.'):t('O impostor não foi identificado.','The impostor was not identified.')}</div><p class="hint">${t('Resultado definido pelo retorno científico: ≥65 sucesso; ≥35 parcial; <35 insucesso.','Outcome defined by scientific return: ≥65 success; ≥35 partial; <35 failure.')}</p></div></div><div class="results">${[[t('O que deu certo?','What went right?'),good,'var(--green)'],[t('O que deu errado?','What went wrong?'),bad,'var(--red)'],[t('O que pode melhorar?','What can improve?'),improve,'var(--yellow)']].map(([title,items,c])=>`<section class="panel" style="border-top:5px solid ${c}"><h3>${title}</h3><ul>${items.map(s=>`<li>${s}</li>`).join('')}</ul></section>`).join('')}</div><details class="panel"><summary>${t('Ver componentes usados','View selected components')}</summary>${selectedList()}</details><div class="actions"><button class="primary" id="retry" ${disabled()}>${t('Tentar novamente ↻','Try again ↻')}</button><button id="returnHome">${t('Voltar ao início','Return home')}</button><button id="download">${t('Baixar relatório ↓','Download report ↓')}</button></div>${room?onlineChat():''}`);$('#retry').onclick=()=>{review=false;event=false;if(room)act('retry');else{state.eventChoice=null;screen=4;render()}};$('#returnHome').onclick=()=>{exitRoom();screen=1;render()};$('#download').onclick=()=>{const text=['MARCO 04 SPACE',missions()[state.mission].name,status,`${r.score}/100`,`${t('Ciência','Science')}: ${r.science}%`,...good,...bad,...improve,t('Dados simulados.','Simulated data.')].join('\n\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.href=url;a.download='marco04-report.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};bindChat()}
function change(key,value){if(room){act('change',{key,value});return}if(key==='instrument')state.instruments=state.instruments.includes(value)?state.instruments.filter(x=>x!==value):[...state.instruments,value];else state[key]=value;render()}
function advance(to){if(room)act('advance',{to});else{screen=to;render()}}
// Online API: rooms and roles come from the server; links never create a local imitation.
const errorText={NO_SERVER:()=>t('Sem servidor online. Inicie o servidor incluído e acesse o endereço HTTP. O arquivo HTML funciona somente no modo presencial.','No online server. Start the included server and open its HTTP address. The HTML file supports in-person play only.'),FULL:()=>t('Esta sala já tem quatro participantes.','This room already has four participants.'),NOT_FOUND:()=>t('Sala não encontrada ou expirada.','Room not found or expired.'),NAME:()=>t('Use um nome diferente, com 1 a 24 caracteres.','Use a different name, 1 to 24 characters long.'),HOST:()=>t('Somente o anfitrião pode realizar esta ação.','Only the host can perform this action.'),READY:()=>t('São necessários quatro jogadores e todos devem confirmar a revelação.','Four players are required and everyone must confirm their role reveal.'),INVALID:()=>t('Ação inválida para esta etapa. Revise os limites da missão.','Invalid action for this step. Review mission constraints.'),AUTH:()=>t('Sessão inválida. Reabra o link no navegador usado para entrar.','Invalid session. Reopen the link in the browser used to join.'),NETWORK:()=>t('Conexão perdida. Tentando reconectar…','Connection lost. Reconnecting…'),RATE:()=>t('Muitas ações. Aguarde e tente novamente.','Too many actions. Wait and try again.')};
function err(code){return (errorText[code]||errorText.NETWORK)()}
async function api(path,body){if(location.protocol==='file:')throw Error('NO_SERVER');let r;try{r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json',...(session?{'Authorization':'Bearer '+session.token}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(6000)})}catch{throw Error('NETWORK')}let j;try{j=await r.json()}catch{throw Error('NO_SERVER')}if(!r.ok)throw Error(j.error||'NETWORK');return j}
async function checkServer(){const el=$('#serverStatus');try{const j=await api('health');if(j.service!=='marco04')throw Error('NO_SERVER');if(!el?.isConnected)return;el.textContent=t('Servidor conectado. As partidas são sincronizadas de verdade.','Server connected. Games are truly synchronized.');el.classList.add('success');$('#create').disabled=false}catch{if(el?.isConnected){el.textContent=err('NO_SERVER');el.classList.add('error')}}}
async function createRoom(){const name=$('#onlineName').value.trim();if(!name){$('#serverStatus').textContent=err('NAME');return}$('#create').disabled=true;try{const j=await api('rooms',{name});joinSession(j);await poll()}catch(e){$('#serverStatus').textContent=err(e.message);$('#create').disabled=false}}
function joinSession(j){pendingInvite=null;session={id:j.id,token:j.token,host:j.host};localStorage.setItem('m04-room-'+j.id,JSON.stringify(session));history.replaceState(null,'','#room='+j.id);mode='online';room={id:j.id};lastVersion=-1;showRole=false;clearInterval(poller);poller=setInterval(poll,1400)}
let polling=false;
async function poll(){if(!session||polling)return;polling=true;try{const j=await api('rooms/'+session.id);connection=true;room=j;players=j.players;state=j.state;screen=j.stage;event=j.launched;session.host=j.isHost;const changed=j.version!==lastVersion;lastVersion=j.version;if(changed)render();const c=$('#connection');if(c){c.textContent=t('● Conectado','● Connected');c.className='status'}}catch(e){connection=false;const c=$('#connection');if(c){c.textContent=err(e.message);c.className='status offline'}if(e.message==='NOT_FOUND'){clearInterval(poller);showModal(`<h2>${err(e.message)}</h2><p>${t('As salas duram até seis horas e são apagadas se o servidor reiniciar.','Rooms last up to six hours and are cleared when the server restarts.')}</p><button id="expiredHome">${t('Voltar ao início','Return home')}</button>`);$('#expiredHome').onclick=()=>{$('#modal').close();exitRoom();screen=1;render()}}}finally{polling=false}}
async function act(type,data={}){try{await api('rooms/'+session.id+'/action',{type,...data});await poll()}catch(e){showModal(`<p class="notice error">${err(e.message)}</p>`)}}
function onlineLobby(){if(room.phase==='roles'){const me=room.me;view(`<div class="role panel"><div id="connection" class="status">${t('● Conectado','● Connected')}</div><div class="eyebrow">${t('Sua identidade secreta','Your secret identity')}</div>${astronaut(me.color)}<h2>${escapeHTML(me.name)}</h2>${showRole?roleHTML(me):`<p>${t('Revele sua função somente neste dispositivo.','Reveal your role only on this device.')}</p>`}<button class="primary" id="privateReveal">${showRole?t('Ocultar função','Hide role'):t('Revelar minha função','Reveal my role')}</button><div class="actions" style="justify-content:center"><button id="ready" ${!showRole||me.ready?'disabled':''}>${me.ready?t('✓ Pronto','✓ Ready'):t('Li minha função. Estou pronto.','I read my role. I’m ready.')}</button></div><p>${players.filter(x=>x.ready).length}/4 ${t('participantes prontos','players ready')}</p>${session.host?`<button class="primary" id="beginMission" ${players.every(x=>x.ready)?'':'disabled'}>${t('Ir para a missão →','Open mission briefing →')}</button>`:`<p class="small">${t('Aguardando o anfitrião avançar.','Waiting for the host to continue.')}</p>`}</div>`);$('#privateReveal').onclick=()=>{showRole=!showRole;render()};$('#ready').onclick=()=>act('ready');if($('#beginMission'))$('#beginMission').onclick=()=>{showRole=false;act('advance',{to:3})};return}
const url=new URL(location.href);url.hash='room='+session.id;view(`<div class="eyebrow">${t('02 / Sala online','02 / Online room')} ${escapeHTML(session.id)}</div><h2>${t('A tripulação está chegando.','The crew is arriving.')}</h2><div id="connection" class="status">${connection?t('● Conectado','● Connected'):err('NETWORK')}</div><div class="notice"><label for="shareLink">${t('Link da sala — envie aos outros três participantes','Room link — send to the other three players')}</label><div class="share"><input id="shareLink" value="${escapeHTML(url.href)}" readonly><button id="copy">${t('Copiar','Copy')}</button></div><p class="hint">${['localhost','127.0.0.1'].includes(location.hostname)?t('Este endereço é local. Para outro dispositivo, use o IP deste computador na rede ou um endereço HTTPS público configurado no servidor.','This address is local. For another device, use this computer’s LAN IP or a public HTTPS address configured on the server.'):t('Todos devem abrir o mesmo endereço com o servidor ativo.','Everyone must open the same address while the server is running.')}</p></div><div class="grid four">${[0,1,2,3].map(i=>{const p=players[i];return `<div class="player">${astronaut(i)}<h3 class="name">${p?escapeHTML(p.name):t('Aguardando…','Waiting…')}</h3><span class="small">${characterName(i)}</span>${p?.host?`<div class="tag">${t('Anfitrião','Host')}</div>`:''}</div>`}).join('')}</div><div class="actions">${session.host?`<button class="primary" id="deal" ${players.length===4?'':'disabled'}>${t('Sortear funções →','Assign roles →')}</button>`:`<p>${t('O anfitrião começará quando os quatro entrarem.','The host will begin when all four players have joined.')}</p>`}</div>${onlineChat()}`);$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(url.href);$('#copy').textContent=t('Copiado!','Copied!')}catch{$('#shareLink').select();$('#copy').textContent=t('Selecione e copie','Select and copy')}};if($('#deal'))$('#deal').onclick=()=>act('deal');bindChat()}
function onlineChat(){if(!room)return '';return `<div class="review"><h3>${t('Rádio da equipe','Crew radio')}</h3><div id="chatlog" class="chatlog" aria-live="polite">${(room.chat||[]).map(m=>`<div><b>${escapeHTML(m.name)}:</b> ${escapeHTML(m.text)}</div>`).join('')}</div><form id="chatForm"><label class="sr-only" for="chatText">${t('Mensagem','Message')}</label><input id="chatText" maxlength="240" placeholder="${t('Sua mensagem…','Your message…')}" autocomplete="off"><button type="submit" style="margin-top:8px">${t('Enviar','Send')}</button></form></div>`}
function bindChat(){const f=$('#chatForm');if(f)f.onsubmit=e=>{e.preventDefault();const input=$('#chatText'),text=input.value.trim();if(text){input.value='';act('chat',{text})}}}
function exitRoom(){clearInterval(poller);poller=null;room=null;session=null;pendingInvite=null;mode='local';players=[];history.replaceState(null,'',location.pathname+location.search);lastVersion=-1}
async function incoming(id){pendingInvite=id;mode='online';screen=2;const stored=localStorage.getItem('m04-room-'+id);if(stored){try{session=JSON.parse(stored);await api('rooms/'+id);joinSession(session);await poll();return}catch{session=null;localStorage.removeItem('m04-room-'+id)}}header();app.innerHTML=nav()+`<div class="role panel"><h2>${t('Entrar na tripulação','Join the crew')}</h2><p>${t('Sala','Room')} ${escapeHTML(id)}</p><label>${t('Seu nome','Your name')}<input id="joinName" maxlength="24" autocomplete="off"></label><p id="joinError" role="alert"></p><button class="primary" id="join">${t('Entrar na sala','Join room')}</button><p class="small">${t('Use um dispositivo ou navegador diferente para cada jogador.','Use a different device or browser for each player.')}</p></div>`;$('#join').onclick=async()=>{try{const j=await api('rooms/'+id+'/join',{name:$('#joinName').value.trim()});joinSession(j);await poll()}catch(e){$('#joinError').textContent=err(e.message)}}}
const invite=new URLSearchParams(location.hash.slice(1)).get('room');if(invite&&/^[a-f0-9]{12}$/.test(invite))incoming(invite);else render();
